<section class="panel"><header class="panel-head"><div><span class="eyebrow">Invoice exception governance</span><h2>Disputes, waivers, credits, and holds</h2></div><span class="panel-meta"><?= count($exceptions) ?> exception(s)</span></header><div class="compact-list"><?php foreach($exceptions as $exception): ?><article><div><strong><?= h($exception['exception_number'].' · '.status_label($exception['exception_type'])) ?></strong><small><?= money($exception['disputed_amount']) ?> · due <?= h(date_us($exception['due_date'])) ?> · <?= h($exception['resolution_note']) ?></small></div><div class="right-summary"><?= badge($exception['status']) ?><b><?= money($exception['supplier_credit_amount']) ?> credit</b></div><?php if(can('purchase_orders.review')): ?><form class="compact-form" action="<?= h(app_url('fulfillment-action.php')) ?>" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="update_exception"><input type="hidden" name="id" value="<?= (int)$exception['id'] ?>"><label><span>Status</span><select name="status"><?php foreach(fulfillment_exception_statuses() as $value): ?><option value="<?= h($value) ?>" <?= $exception['status']===$value?'selected':'' ?>><?= h(status_label($value)) ?></option><?php endforeach; ?></select></label><label><span>Supplier credit</span><input type="number" min="0" step="0.01" name="supplier_credit_amount" value="<?= h((string)$exception['supplier_credit_amount']) ?>"></label><label class="span-2"><span>Resolution evidence</span><textarea name="resolution_note"><?= h($exception['resolution_note']) ?></textarea></label><label class="span-2"><span>Waiver rationale</span><textarea name="waiver_reason"><?= h($exception['waiver_reason']) ?></textarea></label><div class="span-2"><button class="button secondary" type="submit">Update Exception</button></div></form><?php endif; ?></article><?php endforeach; ?><?php if(!$exceptions): render_empty_state('No invoice exceptions','Matched invoices within policy tolerance have no active exception record.'); endif; ?></div></section>
